  1664                                          break;
  1665                          }
  1666                          else if ((flags & STRING_COMPACT_WHITESPACE) &&
  1667                              isspace(*a)) {
  1668                                  a++;
  1669                                  if (isspace(*b++)) {
  1670                                          if (!isspace(*a))
  1671                                                  while (b < eb && isspace(*b))
  1672                                                          b++;
  1673                                  }
  1674                                  else {
  1675                                          v = 1;
  1676                                          break;
  1677                                  }
  1678                          }
