  1680                              isspace(*a)) {
  1681                                  a++;
  1682                                  while (b < eb && isspace(*b))
  1683                                          b++;
  1684                          }
  1685                          else {
  1686                                  if ((v = *b++ - *a++) != '\0')
  1687                                          break;
  1688                          }
  1689                  }
  1690          }
  1691          return v;
